CREATE OR REPLACE FUNCTION public.join_class_by_code(p_code text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ DECLARE c public.classes; enrollment public.class_students; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Vui lòng đăng nhập'; END IF; SELECT * INTO c FROM public.classes WHERE lower(join_code)=lower(trim(p_code)) AND is_active=true AND approval_status='approved' ORDER BY created_at LIMIT 1 FOR UPDATE; IF c.id IS NULL THEN RAISE EXCEPTION 'Mã lớp không hợp lệ hoặc lớp chưa mở'; END IF; SELECT * INTO enrollment FROM public.class_students WHERE class_id=c.id AND student_id=auth.uid() LIMIT 1; IF enrollment.id IS NOT NULL THEN IF enrollment.status='active' THEN RETURN c.id; ELSE RAISE EXCEPTION 'Bạn đã có hồ sơ tại lớp này, vui lòng liên hệ giáo viên'; END IF; END IF; IF (SELECT count(*) FROM public.class_students WHERE class_id=c.id AND status='active') >= COALESCE(c.max_students,30) THEN RAISE EXCEPTION 'Lớp đã đủ học viên'; END IF; INSERT INTO public.class_students(class_id,student_id,status) VALUES(c.id,auth.uid(),'active'); RETURN c.id; END $$;
REVOKE ALL ON FUNCTION public.join_class_by_code(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.join_class_by_code(text) TO authenticated;
CREATE OR REPLACE FUNCTION public.send_class_announcement(p_class_id uuid,p_title text,p_message text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE n integer; BEGIN IF auth.uid() IS NULL OR NOT (public.is_class_teacher(p_class_id,auth.uid()) OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Không có quyền gửi thông báo'; END IF; IF length(trim(p_title)) NOT BETWEEN 1 AND 200 OR length(trim(p_message)) NOT BETWEEN 1 AND 5000 THEN RAISE EXCEPTION 'Nội dung thông báo không hợp lệ'; END IF; INSERT INTO public.notifications(user_id,title,message,type,link) SELECT DISTINCT student_id,trim(p_title),trim(p_message),'info','/learn/classes/'||p_class_id FROM public.class_students WHERE class_id=p_class_id AND status='active'; GET DIAGNOSTICS n=ROW_COUNT; INSERT INTO public.class_messages(class_id,sender_id,message_text) VALUES(p_class_id,auth.uid(),trim(p_title)||E'\n'||trim(p_message)); RETURN n; END $$;
REVOKE ALL ON FUNCTION public.send_class_announcement(uuid,text,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.send_class_announcement(uuid,text,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.purchase_store_item_xp(p_item_id uuid,p_equip boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE item public.store_items; xp integer; spent bigint; remaining bigint; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Vui lòng đăng nhập'; END IF; PERFORM 1 FROM public.profiles WHERE user_id=auth.uid() FOR UPDATE; SELECT * INTO item FROM public.store_items WHERE id=p_item_id AND is_active=true; IF item.id IS NULL OR item.price_xp<=0 THEN RAISE EXCEPTION 'Vật phẩm chưa mở bán bằng XP'; END IF; SELECT total_xp INTO xp FROM public.user_progress WHERE user_id=auth.uid() FOR UPDATE; SELECT COALESCE(sum(amount_paid),0) INTO spent FROM public.user_inventory WHERE user_id=auth.uid() AND purchased_with='xp'; remaining:=GREATEST(0,COALESCE(xp,0)-spent); IF NOT EXISTS(SELECT 1 FROM public.user_inventory WHERE user_id=auth.uid() AND item_code=item.code) THEN IF COALESCE((SELECT streak FROM public.user_progress WHERE user_id=auth.uid()),0)<COALESCE(item.req_streak,0) THEN RAISE EXCEPTION 'Chưa đủ chuỗi ngày học'; END IF; IF remaining<item.price_xp THEN RAISE EXCEPTION 'Không đủ XP'; END IF; INSERT INTO public.user_inventory(user_id,item_id,item_code,purchased_with,amount_paid) VALUES(auth.uid(),item.id,item.code,'xp',item.price_xp); remaining:=remaining-item.price_xp; END IF; IF p_equip AND item.category='avatar_frame' THEN UPDATE public.profiles SET equipped_frame_code=item.code,updated_at=now() WHERE user_id=auth.uid(); END IF; RETURN jsonb_build_object('balance',remaining,'code',item.code,'equipped',p_equip AND item.category='avatar_frame'); END $$;
REVOKE ALL ON FUNCTION public.purchase_store_item_xp(uuid,boolean) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.purchase_store_item_xp(uuid,boolean) TO authenticated;
CREATE OR REPLACE FUNCTION public.equip_owned_avatar_frame(p_code text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Vui lòng đăng nhập'; END IF; IF p_code IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.user_inventory i JOIN public.store_items s ON s.id=i.item_id WHERE i.user_id=auth.uid() AND i.item_code=p_code AND s.category='avatar_frame') THEN RAISE EXCEPTION 'Bạn chưa sở hữu khung này'; END IF; UPDATE public.profiles SET equipped_frame_code=p_code,updated_at=now() WHERE user_id=auth.uid(); IF NOT FOUND THEN RAISE EXCEPTION 'Không tìm thấy hồ sơ'; END IF; END $$;
REVOKE ALL ON FUNCTION public.equip_owned_avatar_frame(text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.equip_owned_avatar_frame(text) TO authenticated;
DROP POLICY IF EXISTS "Users can insert into own inventory" ON public.user_inventory;
CREATE POLICY "Inventory grants by admins only" ON public.user_inventory FOR INSERT TO authenticated WITH CHECK(public.has_role(auth.uid(),'admin'));
CREATE OR REPLACE FUNCTION public.validate_equipped_frame() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NEW.equipped_frame_code IS DISTINCT FROM OLD.equipped_frame_code AND NEW.equipped_frame_code IS NOT NULL AND auth.uid() IS NOT NULL AND NOT public.has_role(auth.uid(),'admin') AND NOT EXISTS(SELECT 1 FROM public.user_inventory WHERE user_id=NEW.user_id AND item_code=NEW.equipped_frame_code) THEN RAISE EXCEPTION 'Khung avatar chưa được mua'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_equipped_frame_before_update BEFORE UPDATE OF equipped_frame_code ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.validate_equipped_frame();
CREATE OR REPLACE FUNCTION public.shift_class_sessions(p_class_id uuid,p_updates jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE u jsonb; BEGIN IF auth.uid() IS NULL OR NOT(public.is_class_teacher(p_class_id,auth.uid()) OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Không có quyền sửa lịch'; END IF; PERFORM 1 FROM public.classes WHERE id=p_class_id FOR UPDATE; FOR u IN SELECT value FROM jsonb_array_elements(p_updates) LOOP IF NOT EXISTS(SELECT 1 FROM public.class_sessions WHERE id=(u->>'id')::uuid AND class_id=p_class_id AND status='scheduled') THEN RAISE EXCEPTION 'Lịch đã thay đổi, hãy tải lại'; END IF; END LOOP; FOR u IN SELECT value FROM jsonb_array_elements(p_updates) LOOP UPDATE public.class_sessions SET session_date=(u->>'newDate')::date,updated_at=now() WHERE id=(u->>'id')::uuid AND class_id=p_class_id; END LOOP; IF EXISTS(SELECT 1 FROM public.class_sessions WHERE class_id=p_class_id AND status<>'cancelled' GROUP BY session_date,start_time HAVING count(*)>1) THEN RAISE EXCEPTION 'Lịch mới trùng buổi học khác'; END IF; END $$;
REVOKE ALL ON FUNCTION public.shift_class_sessions(uuid,jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.shift_class_sessions(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.create_class_makeup(p_class_id uuid,p_session jsonb,p_replaced_id uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; BEGIN IF auth.uid() IS NULL OR NOT(public.is_class_teacher(p_class_id,auth.uid()) OR public.has_role(auth.uid(),'admin')) THEN RAISE EXCEPTION 'Không có quyền sửa lịch'; END IF; PERFORM 1 FROM public.classes WHERE id=p_class_id FOR UPDATE; IF EXISTS(SELECT 1 FROM public.class_sessions WHERE class_id=p_class_id AND session_date=(p_session->>'session_date')::date AND start_time=(p_session->>'start_time')::time AND status<>'cancelled') THEN RAISE EXCEPTION 'Ngày và giờ này đã có buổi học'; END IF; IF nullif(p_session->>'end_time','')::time <= (p_session->>'start_time')::time THEN RAISE EXCEPTION 'Giờ kết thúc phải sau giờ bắt đầu'; END IF; IF p_replaced_id IS NOT NULL THEN UPDATE public.class_sessions SET status='cancelled',updated_at=now() WHERE id=p_replaced_id AND class_id=p_class_id AND status='scheduled'; IF NOT FOUND THEN RAISE EXCEPTION 'Buổi cần học bù không còn ở trạng thái chờ học'; END IF; END IF; INSERT INTO public.class_sessions(class_id,session_date,start_time,end_time,topic,notes,location,meet_link,status,is_makeup,created_by) VALUES(p_class_id,(p_session->>'session_date')::date,(p_session->>'start_time')::time,nullif(p_session->>'end_time','')::time,p_session->>'topic',p_session->>'notes',p_session->>'location',p_session->>'meet_link','makeup',true,auth.uid()) RETURNING id INTO sid; RETURN sid; END $$;
REVOKE ALL ON FUNCTION public.create_class_makeup(uuid,jsonb,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.create_class_makeup(uuid,jsonb,uuid) TO authenticated;